    pose proof (I : lx_noaceil) as LXNOACEIL.  (* [comment removed for export] *)
    intros ra gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 a6 a7 szj tfj SP F fc m ws v d
      HL HSZ HTR HTF SR LNK0 CH0 VR GOT PGS INI TSD TPC TSA CTH THR TSW UNW ST LOIMG SPL SPK SCS MI ->.
    destruct TOPUB as [TU1 TU2].
    destruct RNG as (R1 & R2 & R3 & R4 & R5). destruct STKB as [K0 K1]. destruct TOPB as (T1 & T2 & T3).
    destruct BPB as [B0 BPA]. destruct TB as (TB1 & TB2 & TB3 & TB4). destruct TSEP as (TS1 & TS2 & TS3).
